int h2get_hpack_decode(struct h2get_hpack_ctx *hhc, char *inputs, size_t plen, struct list *headers)
{
    uint8_t *new_buf, *buf = (uint8_t *)inputs;
    uint8_t *end = (uint8_t *)(inputs + plen);
    unsigned long i;
    int nr_headers = 0;

    while (buf < end) {
        int prefix = -1;
        int needs_indexing = 0;
        struct h2get_decoded_header *dh;

        if (*buf & 0x80) {
            /* 6.1.  Indexed Header Field Representation */
            new_buf = decode_int(buf, end, 7, &i);
            if (!new_buf || !i) {
                return -1;
            }
            buf = new_buf;
            if (!add_one_header(hhc, i, headers, &nr_headers, &buf, end, 1)) {
                return -1;
            }
            continue;
        } else if (*buf & 0x40) {
            needs_indexing = 1;
            /* 6.2.1.  Literal Header Field with Incremental Indexing */
            if (*buf & 0x3f)
                prefix = 6;
            else
                prefix = 0;
        } else if (!(*buf & 0xf0)) {
            /* 6.2.2.  Literal Header Field without Indexing */
            if (*buf & 0x0f)
                prefix = 4;
            else
                prefix = 0;
        } else if (*buf & 0x10) {
            /* 6.2.3.  Literal Header Field Never Indexed */
            if (*buf & 0x0f)
                prefix = 4;
            else
                prefix = 0;

        } else if (*buf & 0x20) {
            /* 6.3.  Dynamic Table Size Update */
            new_buf = decode_int(buf, end, 5, &i);
            if (!new_buf) {
                return 0;
            }
            buf = new_buf;
            /* FIXME: take `i` into account */
            continue;
        }

        switch (prefix) {
        case -1:
